import React, { useState } from 'react';
import { Globe, Lock, User } from 'lucide-react';
import { translations } from '../translations';
import { Language, Theme } from '../types';

interface LoginProps {
  onLogin: (status: boolean) => void;
  lang: Language;
  toggleLang: () => void;
  theme: Theme;
}

const Login: React.FC<LoginProps> = ({ onLogin, lang, toggleLang, theme }) => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const t = translations[lang];

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (username === 'mahesh' && password === 'bhujbal') {
      onLogin(true);
    } else {
      setError(t.loginError);
    }
  };

  const themeClasses = {
    bg: theme === 'green' ? 'bg-emerald-50' : 'bg-orange-50',
    cardHeader: theme === 'green' ? 'bg-emerald-600' : 'bg-orange-600',
    cardBorder: theme === 'green' ? 'border-emerald-100' : 'border-orange-100',
    logoBorder: theme === 'green' ? 'border-white/30' : 'border-white/30',
    button: theme === 'green' ? 'bg-emerald-600 hover:bg-emerald-700' : 'bg-orange-600 hover:bg-orange-700',
    focusRing: theme === 'green' ? 'focus:ring-emerald-500' : 'focus:ring-orange-500',
    accent: theme === 'green' ? 'text-emerald-100' : 'text-orange-100'
  };

  return (
    <div className={`min-h-screen flex items-center justify-center ${themeClasses.bg} p-6`}>
      <div className="max-w-md w-full">
        <div className={`bg-white rounded-3xl shadow-xl overflow-hidden border ${themeClasses.cardBorder}`}>
          <div className={`${themeClasses.cardHeader} p-10 text-white text-center relative`}>
            <button 
              onClick={toggleLang}
              className="absolute top-4 right-4 flex items-center gap-2 px-3 py-1 bg-white/20 hover:bg-white/30 rounded-full text-xs font-bold transition-colors"
            >
              <Globe size={14} />
              {lang.toUpperCase()}
            </button>
            
            <div className={`bg-white w-52 h-52 rounded-3xl mx-auto flex items-center justify-center mb-6 transform hover:scale-105 transition-transform shadow-2xl overflow-hidden p-2 border-4 ${themeClasses.logoBorder}`}>
              <img 
                src="data:image/png;base64," 
                alt="Only Indigenous Farm" 
                className="w-full h-full object-contain scale-105" 
                onError={(e) => { e.currentTarget.src = 'https://placehold.co/200x200?text=OIF'; }}
              />
            </div>
            
            <h1 className="text-2xl font-bold tracking-tight uppercase leading-tight">{t.appName}</h1>
            <p className={`${themeClasses.accent} mt-2 text-sm opacity-90`}>{t.welcomeBack}</p>
          </div>
          
          <form onSubmit={handleSubmit} className="p-8 space-y-6">
            {error && (
              <div className="bg-red-50 text-red-600 p-3 rounded-xl text-sm text-center font-bold border border-red-100">
                {error}
              </div>
            )}
            
            <div className="space-y-2">
              <label className="text-sm font-bold text-gray-700 block ml-1">{t.username}</label>
              <div className="relative">
                <User className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                <input
                  type="text"
                  value={username}
                  onChange={(e) => setUsername(e.target.value)}
                  className={`w-full pl-12 pr-4 py-4 bg-gray-50 border border-gray-200 rounded-2xl outline-none transition-all ${themeClasses.focusRing} focus:ring-2`}
                  placeholder="Enter username"
                  required
                />
              </div>
            </div>

            <div className="space-y-2">
              <label className="text-sm font-bold text-gray-700 block ml-1">{t.password}</label>
              <div className="relative">
                <Lock className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                <input
                  type="password"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  className={`w-full pl-12 pr-4 py-4 bg-gray-50 border border-gray-200 rounded-2xl outline-none transition-all ${themeClasses.focusRing} focus:ring-2`}
                  placeholder="Enter password"
                  required
                />
              </div>
            </div>

            <button
              type="submit"
              className={`w-full py-4 ${themeClasses.button} text-white font-bold rounded-2xl shadow-lg transition-all active:scale-[0.98] mt-2`}
            >
              {t.login}
            </button>
          </form>
        </div>
      </div>
    </div>
  );
};

export default Login;